const fs = require('fs');
const path = require('path');

const files = ['a.txt', 'b.txt', 'c.txt'];
const results = [];

for (const file of files) {
  const raw = fs.readFileSync(path.join(__dirname, file), 'utf8');
  if (raw.includes('\uFFFD')) throw new Error(`${file}: invalid UTF-8 replacement char`);

  // Parser 1: full-line regex, requires exactly one population line.
  const lines = raw.split('\n').filter((l) => l.trim() !== '');
  if (lines.length !== 1) throw new Error(`${file}: expected 1 non-empty line, got ${lines.length}`);
  const m = lines[0].match(/^([A-Za-z]+) population: (\d+)$/);
  if (!m) throw new Error(`${file}: line does not match "<Name> population: <int>": ${JSON.stringify(lines[0])}`);

  // Parser 2: independent split-based parse, cross-checks parser 1.
  const [labelPart, numPart] = lines[0].split(': ');
  const label2 = labelPart.replace(/ population$/, '');
  const num2 = Number(numPart);
  if (!Number.isInteger(num2) || String(num2) !== numPart)
    throw new Error(`${file}: second parser disagrees on number ${JSON.stringify(numPart)}`);
  const num1 = Number(m[2]);
  if (num1 !== num2 || label2 !== m[1])
    throw new Error(`${file}: parsers disagree (${m[1]}/${num1} vs ${label2}/${num2})`);

  // Cross-check: only digit run in the file is the population itself.
  const digits = raw.match(/\d+/g) || [];
  if (digits.length !== 1 || digits[0] !== m[2])
    throw new Error(`${file}: unexpected numeric content ${JSON.stringify(digits)}`);

  results.push({ file, label: m[1], population: num1, bytes: Buffer.byteLength(raw) });
}

const total = results.reduce((s, r) => s + r.population, 0);
if (!Number.isSafeInteger(total)) throw new Error('total is not a safe integer');

console.log('per-file cross-check OK:', JSON.stringify(results));
console.log('total:', total);

fs.writeFileSync(path.join(__dirname, 'answer.json'), JSON.stringify({ total }) + '\n', 'utf8');
console.log('wrote answer.json');

